# survey practice invoices: which contracts exist, currencies
import sys; sys.path.insert(0,'grader')
from extract import Mailbox, attachments
from pathlib import Path
import re
mb=Mailbox(str(Path('data/scenarios')))
seen=set()
for f in sorted(Path('data/scenarios').glob('batch_*/[0-9]*.eml')):
    for name,data in attachments(f.read_bytes()):
        if name.endswith('.pdf'):
            pages,scan=mb.pages(f"{f.parent.name}/{f.name}#{name}")
            t=pages[0][:600]
            m=re.search(r'Contract\s+([A-Z0-9/-]+)\s+Currency\s+([A-Z]{3})', t)
            cur=re.search(r'(?:Total|Charges)\s+(INR|USD|EUR|GBP)\s', t)
            if m or cur:
                key=(m.group(1) if m else None, cur.group(1) if cur else None)
                seen.add(key)
for k in sorted(seen, key=str): print(k)
EOF

