# How big are the practice/exam batches? count attachments per batch (cost/time pressure)
import sys; sys.path.insert(0,'grader')
from extract import attachments
from pathlib import Path
for root in ['data/scenarios','data/exam']:
    for b in sorted(Path(root).glob('batch_*')):
        n_email=n_att=0; sz=0; types={}
        for f in sorted(b.glob('*.eml')):
            n_email+=1; sz+=f.stat().st_size
            for name,data in attachments(f.read_bytes()):
                n_att+=1; types[name.rsplit('.',1)[-1]]=types.get(name.rsplit('.',1)[-1],0)+1; sz+=len(data)
        print(root, b.name, f"{n_email} emails, {n_att} attachments, {sz/1e6:.1f} MB, {types}")
EOF

